function dependencies(chromium){const modules=[];for(const n of ['playwright','playwright-core']){const root=fs.realpathSync(path.dirname(require.resolve(n+'/package.json'))),pkg=JSON.parse(fs.readFileSync(path.join(root,'package.json'),'utf8')),files=[];assert.equal(pkg.version,'1.62.1','Existing approved 1.62.1 only; no installation.');function visit(dir,rel=''){for(const entry of fs.readdirSync(dir,{withFileTypes:true}).sort((a,b)=>a.name.localeCompare(b.name,'en'))){assert.equal(entry.isSymbolicLink(),false);const filename=path.join(dir,entry.name),name=rel?rel+'/'+entry.name:entry.name;if(entry.isDirectory())visit(filename,name);else{assert.equal(entry.isFile(),true);files.push({path:name,...identity(filename)});}}}visit(root);modules.push({root,version:pkg.version,files});}const executable=chromium.executablePath();assert.equal(fs.realpathSync(executable),fs.realpathSync(path.join(BASE,'work','browser-test-cache-20261105','chromium-1234','chrome-win64','chrome.exe')));return {modules,executable:{path:executable,...identity(executable)}};}
function crc(bytes){let value=0xffffffff;for(const b of bytes){value^=b;for(let i=0;i<8;i++)value=value&1?0xedb88320^(value>>>1):value>>>1;}return (value^0xffffffff)>>>0;}
