function unzip(bytes){assert.ok(bytes.length>=22);const end=bytes.length-22;assert.equal(bytes.readUInt32LE(end),0x06054b50);assert.equal(bytes.readUInt16LE(end+20),0);assert.equal(bytes.readUInt16LE(end+4),0);assert.equal(bytes.readUInt16LE(end+6),0);const count=bytes.readUInt16LE(end+10),central=bytes.readUInt32LE(end+16),centralBytes=bytes.readUInt32LE(end+12);assert.equal(bytes.readUInt16LE(end+8),count);assert.equal(central+centralBytes,end);assert.equal(count,4,'HTML + two actual attachments + manifest');let at=0;const files=[];while(at<central){const offset=at;assert.equal(bytes.readUInt32LE(at),0x04034b50);assert.equal(bytes.readUInt16LE(at+6),0x800);assert.equal(bytes.readUInt16LE(at+8),0);const checksum=bytes.readUInt32LE(at+14),length=bytes.readUInt32LE(at+18),nameLength=bytes.readUInt16LE(at+26);assert.equal(bytes.readUInt32LE(at+22),length);assert.equal(bytes.readUInt16LE(at+28),0);const name=new TextDecoder('utf-8',{fatal:true}).decode(bytes.subarray(at+30,at+30+nameLength)),start=at+30+nameLength,data=bytes.subarray(start,start+length);assert.ok(!name.includes('..')&&!name.includes('\\')&&!name.startsWith('/'));assert.equal(data.length,length);assert.equal(crc(data),checksum);files.push({name,data,offset,checksum});at=start+length;}assert.equal(at,central);assert.equal(files.length,count);assert.equal(new Set(files.map(f=>f.name)).size,count);for(const f of files){assert.equal(bytes.readUInt32LE(at),0x02014b50);assert.equal(bytes.readUInt16LE(at+8),0x800);assert.equal(bytes.readUInt16LE(at+10),0);assert.equal(bytes.readUInt32LE(at+16),f.checksum);assert.equal(bytes.readUInt32LE(at+20),f.data.length);assert.equal(bytes.readUInt32LE(at+24),f.data.length);assert.equal(bytes.readUInt32LE(at+42),f.offset);const n=bytes.readUInt16LE(at+28);assert.equal(bytes.readUInt16LE(at+30),0);assert.equal(bytes.readUInt16LE(at+32),0);assert.equal(bytes.subarray(at+46,at+46+n).toString('utf8'),f.name);at+=46+n;}assert.equal(at,end);return files;}
function csvRows(bytes){assert.deepEqual([...bytes.subarray(0,3)],[239,187,191]);const text=new TextDecoder('utf-8',{fatal:true}).decode(bytes.subarray(3));let row=[],cell='',quoted=false,rows=[];for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){row.push(cell);cell='';}else if(c==='\r'&&!quoted){assert.equal(text[++i],'\n');row.push(cell);rows.push(row);row=[];cell='';}else cell+=c;}assert.equal(quoted,false);assert.equal(cell,'');assert.deepEqual(row,[]);return rows;}
