  await step('bidder-reload-in-flight-and-failed-credential-verification-never-use-old-pair',async()=>{
   // Gate only this synthetic license's native digest during the genuine IDB read.
   // Other browser calls, product state and IDB operations are unchanged.
   await page.evaluate(needle=>{
    const target=crypto.subtle,orig=target.digest,desc=Object.getOwnPropertyDescriptor(target,'digest');
    const gate={entered:false,released:false};globalThis.__testBidderGate=gate;
    Object.defineProperty(target,'digest',{configurable:true,value:function(algo,buf){
     const data=ArrayBuffer.isView(buf)?new Uint8Array(buf.buffer,buf.byteOffset,buf.byteLength):new Uint8Array(buf);
     if(gate.entered||needle.length!==data.length||!needle.every((x,i)=>data[i]===x))return orig.call(target,algo,buf);
     gate.entered=true;return new Promise((ok,no)=>{gate.release=()=>{gate.released=true;no(Error('SYNTHETIC digest failure'));};});
    }});
    gate.restore=()=>{if(desc)Object.defineProperty(target,'digest',desc);else delete target.digest;delete globalThis.__testBidderGate;};
   },[...originals.business_license.bytes]);
   try{
    await page.click('#bidder-apply');await page.waitForFunction(()=>globalThis.__testBidderGate.entered);
    await expectBlock();assert.ok(!(await page.locator('#credentials-list').innerText()).includes(originals.business_license.name));
    const reg=page.locator('#register-quote');await reg.scrollIntoViewIfNeeded();const b=await reg.boundingBox();await page.mouse.click(b.x+b.width/2,b.y+b.height/2);
    await page.click('.sidebar .nav-item[data-view=ledger]');await ledgerCount(0);await page.click('.sidebar .nav-item[data-view=quote]');await expectBlock();
    await page.evaluate(()=>globalThis.__testBidderGate.release());await text('#bidder-picker-status','未带入');await expectUnselected();
   }finally{await page.evaluate(()=>globalThis.__testBidderGate.restore());}
   await page.selectOption('#bidder-picker-select',own);await text('#bidder-picker-status','已备 2/2');await enabled('#preview');await enabled('#register-quote');
   report.pendingBidderLoadProof={blocksPreview:true,blocksRegistration:true,previousFirmCleared:true,failureLeavesUnselected:true,successfulRetry:true};await sentinel();
  });
